CREATE OR REPLACE FUNCTION calculate_conversion_rate(cohort_month DATE, days_window INTEGER)
RETURNS NUMERIC(5,2) AS $$
DECLARE
  total_signups INT;
  converted_signups INT;
  rate NUMERIC(5,2);
BEGIN
  SELECT COUNT(*)
  INTO total_signups
  FROM trial_signups
  WHERE DATE_TRUNC('month', trial_start_date) = DATE_TRUNC('month', cohort_month);

  IF total_signups = 0 THEN
    RETURN 0.00;
  END IF;

  SELECT COUNT(*)
  INTO converted_signups
  FROM trial_signups
  WHERE DATE_TRUNC('month', trial_start_date) = DATE_TRUNC('month', cohort_month)
    AND converted_at IS NOT NULL
    AND (converted_at - trial_start_date) <= days_window;

  rate := ROUND((converted_signups::NUMERIC / total_signups) * 100, 2);

  RETURN rate;
END;
$$ LANGUAGE plpgsql;

SELECT calculate_conversion_rate('2024-01-01', 14) AS result;
